import hashlib, random

def leading_zero_bits(h: bytes) -> int:
    n = int.from_bytes(h, "big")
    return 256 - n.bit_length()

def mine(data: str, k: int):
    """Cerca il nonce tale che SHA256(SHA256(data||nonce)) abbia almeno k bit zero iniziali."""
    target = 2 ** (256 - k)          # hash < target  <=>  almeno k zeri binari
    nonce = 0
    while True:
        h = hashlib.sha256(hashlib.sha256(f"{data}|{nonce}".encode()).digest()).digest()
        if int.from_bytes(h, "big") < target:
            return nonce, h.hex(), nonce + 1   # tentativi fatti
        nonce += 1

random.seed(1)
for k in (8, 12, 16):
    tries = [mine(f"blocco-{random.random()}", k)[2] for _ in range(60)]
    print(f"k={k:2d}  media tentativi={sum(tries)/len(tries):9.1f}  atteso 2^k={2**k}")

nonce, h, t = mine("header di prova", 16)
print("nonce trovato:", nonce, "hash:", h[:16] + "...", "zeri binari:", leading_zero_bits(bytes.fromhex(h)))

