codeExercises.solution:
import random, math

def stale_rate(block_interval, delay, n_blocks=200_000, seed=7):
    """Frazione di blocchi 'stale': un altro miner trova un blocco mentre quello
    precedente si sta ancora propagando (entro 'delay' secondi)."""
    rng = random.Random(seed)
    stale = 0
    for _ in range(n_blocks):
        # tempo del prossimo blocco concorrente: esponenziale di media block_interval
        if rng.expovariate(1 / block_interval) < delay:
            stale += 1
    return stale / n_blocks

delay = 2.0   # secondi per propagare un blocco a quasi tutta la rete
for interval in (600, 60, 15, 5):
    sim = stale_rate(interval, delay)
    theory = 1 - math.exp(-delay / interval)
    print(f"blocco ogni {interval:4d} s: fork simulate {sim*100:6.3f}%   teoria 1-e^(-d/T) {theory*100:6.3f}%")

# Longest chain rule (slide 86) su un albero di blocchi
class Node:
    def __init__(self):
        self.parent = {"G": None}; self.height = {"G": 0}
        self.head = "G"
    def receive(self, b, p):
        self.parent[b] = p
        self.height[b] = self.height[p] + 1
        if self.height[b] > self.height[self.head]:      # strettamente maggiore: first seen a parità
            old, self.head = self.head, b
            return f"nuova testa {b} (h={self.height[b]}), prima era {old}"
        return f"{b} tenuto da parte (h={self.height[b]}), testa resta {self.head}"
    def chain(self):
        c, b = [], self.head
        while b: c.append(b); b = self.parent[b]
        return list(reversed(c))

n = Node()
for b, p in [("1", "G"), ("2a", "1"), ("2c", "1"), ("3c", "2c"), ("3a", "2a"), ("4a", "3a")]:
    print(n.receive(b, p))
print("catena attiva:", " -> ".join(n.chain()))
